{"explanation":"The law of cosines, c² = a² + b² − 2ab·cos(C), is best read as the Pythagorean theorem plus a correction term. The part a² + b² is what c² *would* equal if angle C were exactly 90°; the term −2ab·cos(C) corrects for the fact that it usually isn't. If C is acute, cos(C) is positive, so the correction subtracts from the Pythagorean sum (the triangle is "pinched" and c is shorter than the hypotenuse would be); if C is obtuse, the correction adds (the triangle is "stretched"). At exactly 90°, cos(C) = 0, the correction vanishes, and you recover the plain Pythagorean theorem — drag point A in the visualization to see the red/green correction segment shrink or grow the bar from a² + b² to c².","manimCode":"const a = 2.5, b = 3.3;
const C0 = [-3.7, -2.2, 0];
const Bv = [-0.4, -2.2, 0];
const S = a * a + b * b;
const TWOAB = 2 * a * b;
let theta = 1.15;

function pointA(th) { return [C0[0] + a * Math.cos(th), C0[1] + a * Math.sin(th), 0]; }
function wedgeVerts(th) {
  const r = 0.6, pts = [[C0[0], C0[1], 0]];
  const n = Math.max(3, Math.ceil(th / 0.07));
  for (let i = 0; i <= n; i++) {
    const t = th * i / n;
    pts.push([C0[0] + r * Math.cos(t), C0[1] + r * Math.sin(t), 0]);
  }
  return pts;
}
function rectVerts(xa, ya, xb, yb) { return [[xa, ya, 0], [xb, ya, 0], [xb, yb, 0], [xa, yb, 0]]; }

// --- triangle ---
const triangle = new Polygon({ vertices: [[C0[0], C0[1], 0], [Bv[0], Bv[1], 0], pointA(theta)], color: WHITE });
triangle.setFill(BLUE_E, 0.35);
triangle.setStrokeWidth(3);
const wedge = new Polygon({ vertices: wedgeVerts(theta), color: YELLOW });
wedge.setFill(YELLOW, 0.45);
const dotA = new Dot({ point: pointA(theta), color: YELLOW });
const dotC = new Dot({ point: [C0[0], C0[1], 0], color: WHITE });
const dotB = new Dot({ point: [Bv[0], Bv[1], 0], color: WHITE });

// --- right-angle ghost (pure Pythagoras reference) ---
const A90 = [C0[0], C0[1] + a, 0];
const ghostSide = new Polygon({ vertices: [[C0[0], C0[1], 0], A90], color: GRAY });
ghostSide.setStrokeWidth(2).setFillOpacity(0).setOpacity(0.55);
const ghostHyp = new Polygon({ vertices: [A90, [Bv[0], Bv[1], 0]], color: GRAY });
ghostHyp.setStrokeWidth(2).setFillOpacity(0).setOpacity(0.55);
const ghostLab = new Text({ text: 'if C = 90°', color: GRAY, fontSize: 18 });
ghostLab.moveTo([-1.55, -0.5, 0]);

// --- bars: a²+b² vs c², with the correction segment between ---
const x0 = 1.9, k = 4.3 / 37;
const vx = (v) => x0 + k * v;
const xS = vx(S);
const c0sq = S - TWOAB * Math.cos(theta);
const pBar = new Polygon({ vertices: rectVerts(x0, 1.55, xS, 1.95), color: BLUE_C });
pBar.setFill(BLUE_C, 0.4);
const cBar = new Polygon({ vertices: rectVerts(x0, 0.85, vx(c0sq), 1.25), color: BLUE });
cBar.setFill(BLUE, 0.85);
const corrSeg = new Polygon({ vertices: rectVerts(Math.min(xS, vx(c0sq)), 1.36, Math.max(xS, vx(c0sq)), 1.48), color: RED });
corrSeg.setFill(RED, 0.9);
const refLine = new Polygon({ vertices: [[xS, 0.78, 0], [xS, 2.02, 0]], color: GRAY });
refLine.setStrokeWidth(1.5).setFillOpacity(0).setOpacity(0.7);
const axisLine = new Polygon({ vertices: [[x0, 0.78, 0], [x0, 2.02, 0]], color: WHITE });
axisLine.setStrokeWidth(1.5).setFillOpacity(0);

// --- labels ---
const sideALab = new Text({ text: 'a', color: WHITE, fontSize: 26 });
const sideBLab = new Text({ text: 'b', color: WHITE, fontSize: 26 });
sideBLab.moveTo([-2.05, -2.56, 0]);
const sideCLab = new Text({ text: 'c', color: WHITE, fontSize: 26 });
const hint = new Text({ text: 'drag A', color: GRAY, fontSize: 18 });
const vC = new Text({ text: 'C', color: WHITE, fontSize: 22 });
vC.moveTo([-4.05, -2.55, 0]);
const vB = new Text({ text: 'B', color: WHITE, fontSize: 22 });
vB.moveTo([-0.25, -2.55, 0]);
const barPLab = new Text({ text: 'a² + b²', color: BLUE_C, fontSize: 22 });
barPLab.moveTo([1.42, 1.75, 0]);
const barCLab = new Text({ text: 'c²', color: BLUE, fontSize: 22 });
barCLab.moveTo([1.62, 1.05, 0]);
const note = new Text({ text: 'Drag A to change angle C — at 90° the correction vanishes: pure Pythagoras!', color: GRAY, fontSize: 24 });
note.moveTo([0, -3.4, 0]);

// --- dynamic texts ---
let thetaTex = null, r1 = null, r2 = null, r3 = null;
function drawText(current, opts, pos) {
  if (current) scene.remove(current);
  const t = new Text(opts);
  t.moveTo(pos);
  scene.add(t);
  return t;
}

function updateAll(th) {
  const cosC = Math.cos(th);
  const corr = -TWOAB * cosC;
  let c2 = S + corr;
  if (c2 < 0.02) c2 = 0.02;
  const A = pointA(th);

  triangle.setVertices([[C0[0], C0[1], 0], [Bv[0], Bv[1], 0], A]);
  wedge.setVertices(wedgeVerts(th));

  const xC = vx(c2);
  cBar.setVertices(rectVerts(x0, 0.85, xC, 1.25));
  const lo = Math.min(xS, xC), hi = Math.max(xS, xC);
  corrSeg.setVertices(rectVerts(lo, 1.36, hi, 1.48));
  const col = (c2 <= S) ? RED : GREEN;
  corrSeg.setColor(col);
  corrSeg.setFill(col, 0.9);

  sideALab.moveTo([C0[0] + (a / 2) * Math.cos(th) - Math.sin(th) * 0.34, C0[1] + (a / 2) * Math.sin(th) + Math.cos(th) * 0.34, 0]);
  const mx = (A[0] + Bv[0]) / 2, my = (A[1] + Bv[1]) / 2;
  let nx = mx - C0[0], ny = my - C0[1];
  const L = Math.hypot(nx, ny) || 1; nx /= L; ny /= L;
  sideCLab.moveTo([mx + nx * 0.4, my + ny * 0.4, 0]);
  hint.moveTo([A[0] + 0.1, A[1] + 0.4, 0]);

  const deg = Math.round(th * 180 / Math.PI);
  const sgn = corr >= 0 ? '+' : '-';
  thetaTex = drawText(thetaTex, { text: deg + '°', color: YELLOW, fontSize: 22 }, [C0[0] + 1.05 * Math.cos(th / 2), C0[1] + 1.05 * Math.sin(th / 2), 0]);
  r1 = drawText(r1, { text: 'C = ' + deg + '°    cos C = ' + cosC.toFixed(2), color: WHITE, fontSize: 24 }, [4.0, 2.75, 0]);
  r2 = drawText(r2, { text: 'correction = -2ab·cos C = ' + sgn + Math.abs(corr).toFixed(2), color: col, fontSize: 24 }, [4.0, 2.28, 0]);
  r3 = drawText(r3, { text: 'c² = ' + S.toFixed(2) + ' ' + sgn + ' ' + Math.abs(corr).toFixed(2) + ' = ' + c2.toFixed(2), color: WHITE, fontSize: 24 }, [4.0, 0.3, 0]);
}

// --- title formula ---
const formula = new MathTex({ latex: "c^2 = \\underbrace{a^2 + b^2}_{\\text{Pythagoras}} \\;+\\; \\underbrace{(-2ab\\cos C)}_{\\text{correction}}", fontSize: 40 });
await formula.waitForRender();
formula.moveTo([0.3, 3.35, 0]);

scene.add(ghostSide, ghostHyp, ghostLab, dotC, dotB, sideBLab, vC, vB, pBar, cBar, corrSeg, refLine, axisLine, barPLab, barCLab, note, sideALab, sideCLab, hint);
await scene.play(new FadeIn(formula));
await scene.play(new AnimationGroup([new Create(triangle), new Create(wedge), new FadeIn(dotA)]));
updateAll(theta);

makeDraggable(dotA, scene, { onDrag: (mob, pos) => {
  let th = Math.atan2(pos[1] - C0[1], pos[0] - C0[0]);
  if (th < 0.25) th = 0.25;
  if (th > Math.PI - 0.25) th = Math.PI - 0.25;
  theta = th;
  mob.moveTo(pointA(th));
  updateAll(th);
}});

await scene.wait(999999);"}

